using System;

namespace StdbModule;

public static partial class ItalianQuotes
{
    public static class PrimoLevi
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Al fascismo di oggi manca soltanto il potere per ridiventare quello che era, e cioè la consacrazione del privilegio e della disuguaglianza.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "C'è Auschwitz, quindi non può esserci Dio. Non trovo una soluzione al dilemma. La cerco, ma non la trovo.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Guai se tutte le frasi reversibili fossero vere, fossero sentenze d'oracolo... eppure quando le leggi a rovescio, e il conto torna, c'è qualcosa in loro di magico e rivelatorio: lo sapevano anche i latini, e le scrivevano sulle meridiane.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Io sono convinto che Israele va difeso, credo nella dolorosa necessità di un esercito efficiente. Ma sono convinto che anche al governo israeliano faccia bene confrontarsi con un nostro appoggio sempre condizionato.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Kafka comprende il mondo (il suo, e anche meglio il nostro d'oggi) con una chiaroveggenza che stupisce, e che ferisce come una luce troppo intensa.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Mi pareva che i fatti che dovevo raccontare contenessero in sé una forza sufficiente per sopportare uno stile medio. In modo che lo stile della scrittura, il suono delle parole, non sopraffacesse mai il contenuto.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "L'esperienza è l'accumulo del da farsi davanti all'imprevisto.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Ma le abbiamo cominciate noi. Il nazismo in Germania è stata una metastasi di un tumore che era in Italia. È un tumore che ha condotto vicino alla morte la Germania e l'Europa, vicino al disastro completo.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Le leggi razziali erano il sintomo di una carnevalata: si era ormai dimenticato il volto criminale del fascismo (quello del delitto Matteotti, per intenderci): rimaneva da vederne quello sciocco.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Oggi nella carriera del chimico, nove volte su dieci la scienza declina sulla tecnologia e la tecnologia declina sulla burocrazia. Direi che nove volte su dieci un chimico è un funzionario, se non addirittura un burocrate, e una volta su dieci è un ricercatore.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "È avvenuto, quindi può accadere di nuovo: questo è il nocciolo di quanto abbiamo da dire.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Non esistono problemi che non possano essere risolti intorno a un tavolo, purché ci sia volontà buona e fiducia reciproca: o anche paura reciproca.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Che «il Gulag fu prima di Auschwitz» è vero; ma non si può dimenticare che gli scopi dei due inferni non erano gli stessi. Il primo era un massacro fra uguali; non si basava su un primato razziale; non divideva l'umanità in superuomini e sottouomini; il secondo si fondava su un'ideologia impregnata di razzismo.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Era di fantasia pedestre e lenta: viveva di sogni come tutti noi, ma i suoi sogni erano saggi, erano ottusi, possibili, contigui alla realtà, non romantici, non cosmici.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Apprezzavo i suoi due testi, chiari fino all'ossessione. Stringati, pregni del suo arcigno disprezzo per l'umanità in generale e per gli studenti pigri e sciocchi in particolare: perché tutti gli studenti, per definizione, erano pigri e sciocchi.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Chi va in caccia non ha che da prendere il fucile, anzi meglio la zagaglia e l'arco, e mettersi per il bosco: il successo e l'insuccesso dipendono solo da lui.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Perché la ruota giri, perché la vita viva, ci vogliono le impurezze, e le impurezze delle impurezze: anche nel terreno, come è noto, se ha da essere fertile. Ci vuole il dissenso, il diverso, il grano di sale e di senape.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Incominciammo a studiare fisica insieme, e Sandro fu stupito quando cercai di spiegargli alcune delle idee che a quel tempo confusamente coltivavo. Che la nobiltà dell'Uomo, acquisita in cento secoli di prove e di errori, era consistita nel farsi signore della materia.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Distillare è bello. Prima di tutto, perché è un mestiere lento, filosofico e silenzioso, che ti occupa ma ti lascia tempo di pensare ad altro, un po' come l'andare in bicicletta.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Già tutte le miniere sono magiche, da sempre. Le viscere della terra brulicano di gnomi, coboldi (cobalto!), niccoli (nichel!), che possono essere generosi e farti trovare il tesoro sotto la punta del piccone, o ingannarti, abbagliarti, facendo rilucere come l'oro la modesta pirite.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Siamo chimici, cioè cacciatori: nostre sono «le due esperienze della vita adulta» di cui parlava Pavese, il successo e l'insuccesso, uccidere la balena bianca o sfasciare la nave; non ci si deve arrendere alla materia incomprensibile, non ci si deve sedere.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Siccome ho visto che queste questioni gli interessavano molto, gli ho spiegato che, se si va oltre le apparenze, il piombo è proprio il metallo della morte: perché fa morire, perché il suo peso è un desiderio di cadere, e cadere è dei cadaveri.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "I conigli non sono animali simpatici. Sono fra i mammiferi più lontani dall'uomo, forse perché le loro qualità sono quelle dell'umanità avvilita e reietta: sono timidi, silenziosi e fuggitivi, e non conoscono che il cibo ed il sesso.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Ma venne in novembre lo sbarco alleato in Nord Africa, venne in dicembre la resistenza e poi la vittoria russa a Stalingrado, e capimmo che la guerra si era fatta vicina e la storia aveva ripreso il suo cammino.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Si esita sempre nel giudicare le azioni temerarie, proprie od altrui, dopo che queste sono andate a buon fine: forse non erano dunque abbastanza temerarie? O forse è vero che esiste un Dio che protegge i bambini, gli stolti e gli ebbri?", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "La consulenza è il lavoro ideale, quello da cui tu trai prestigio e quattrini senza sporcarti le mani, né romperti il filo della schiena, né rischiare di finire abbrustolito o intossicato: devi solo toglierti il camice, mettere la cravatta, ascoltare in attento silenzio il quesito, e ti senti come l'oracolo di Delfo.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Il mestiere di chimico [...] insegna a superare, anzi ad ignorare, certi ribrezzi, che non hanno nulla di necessario né di congenito: la materia è materia, né nobile né vile, infinitamente trasformabile, e non importa affatto quale sia la sua origine prossima.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Ci sono metalli amici e metalli nemici. Lo stagno era un amico: non solo perché, da qualche mese, Emilio ed io ne vivevamo, trasformandolo in cloruro stannoso da vendere ai fabbricanti di specchi, ma anche per altre ragioni più riposte.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "A fare il SAC (Servizio Assistenza Clienti) non si può mandare il primo venuto. È un lavoro delicato e complesso, non molto diverso da quello dei diplomatici: per esercitarlo con successo occorre infondere fiducia nei clienti.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Il laboratorio è luogo da giovani, ed a ritornarci ci si sente ritornare giovani: con la stessa smania di avventura, di scoperta, d'imprevisto, che si ha a diciassette anni.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "L'esperienza insegna che proprio questa, l'affidabilità, è la virtù più costante, quella che non si acquista né si perde con gli anni. Si nasce degni di fiducia, col viso aperto e gli occhi fermi, e tali si resta per la vita.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "La sua carriera era stata ricca di eventi, anche se per lo più, appunto, non erano stati che in bianco e nero: anche la mia? Certo, gli confermai: chimici e non chimici, ma negli ultimi anni gli eventi chimici avevano prevalso, per frequenza e intensità.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Le grane, tu lo saprai, non vengono al galoppo, come gli Unni, ma zitte, di soppiatto, come le epidemie.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Una vernice è una sostanza instabile per definizione: infatti, a un certo punto della sua carriera, da liquida deve diventare solida. È necessario che questo avvenga al momento e nel luogo giusto.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Mi conosco: non posseggo prontezza polemica, l'avversario mi distrae, mi interessa più come uomo che come avversario, lo sto a sentire e rischio di credergli; lo sdegno e il giusto giudizio mi tornano dopo, sulle scale, quando non servono più.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Ammettevo che non tutti nascono eroi, e che un mondo in cui ''tutti'' fossero come lui, cioè onesti ed inermi, sarebbe tollerabile, ma questo è un mondo irreale.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Giunto a questo punto della vita, qualche chimico, davanti alla tabella del Sistema Periodico, o agli indici monumentali del Beilstein o del Landolt, non vi ravvisa sparsi i tristi brandelli, o i trofei, del proprio passato professionale?", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Auschwitz è fuori di noi, ma è intorno a noi, è nell'aria. La peste si è spenta, ma l'infezione serpeggia: sarebbe sciocco negarlo.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "È dell'uomo operare in vista di un fine: la strage di Auschwitz, che ha distrutto una tradizione ed una civiltà, non ha giovato a nessuno.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Esiste un contagio del male: chi è non-uomo disumanizza gli altri, ogni delitto si irradia, si trapianta intorno a sé, corrompe le coscienze e si circonda di complici sottratti con la paura o la seduzione al campo avverso.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Hanno dimostrato per tutti i secoli a venire quali insospettate riserve di ferocia e di pazzia giacciano latenti nell'uomo dopo millenni di vita civile, e questa è opera demoniaca.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "In questa nostra epoca fragorosa e cartacea, piena di propaganda aperta e di suggestioni occulte, di retorica macchinale, di compromessi, di scandali e di stanchezza, la voce della verità, anziché perdersi, acquista un timbro nuovo, un risalto più nitido.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "In realtà, e nonostante alcune contrarie apparenze, il disconoscimento, il vilipendio del valore morale del lavoro era ed è essenziale al mito fascista in tutte le sue forme.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "La maggior parte fra noi erano ebrei: ebrei provenienti da tutte le città italiane, ed anche ebrei stranieri, polacchi, ungheresi, jugoslavi, cechi, tedeschi, che nell'Italia fascista costretta all'antisemitismo dalle leggi razziali di Mussolini, avevano incontrato la benevolenza e la civile ospitalità del popolo italiano.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Nelle intenzioni fasciste, in Italia la caccia all'ebreo non avrebbe dovuto essere meno accanita che nella Germania alleata, ma è stata ampiamente vanificata dalla sensibilità umana degli italiani, dalla indifferenza politica di allora, e dal discredito di cui il fascismo si era ormai coperto.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Ogni tempo ha il suo fascismo: se ne notano i segni premonitori dovunque la concentrazione di potere nega al cittadino la possibilità e la capacità di esprimere ed attuare la sua volontà.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Sarà bene ricordare a chi non sa, ed a chi preferisce dimenticare, che l'olocausto si è esteso anche all'Italia, benché la guerra volgesse ormai alla fine, e benché la massima parte del popolo italiano si sia mostrata immune al veleno razzista.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = " [...] perché il martello aggiusta tutto, tanto che alla Lancia lo chiamavano \"l'ingegnere\".", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Pena e dispetto come fanno i malati, che anche se uno non gli vuole bene finisce col dare una mano perché guariscano, così almeno non si lamentano più.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Non è mica un caso che quelli che hanno più fretta di fare il funerale sono proprio quelli che sentono più colpa.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Lei deve sapere che farmi avanti quando tutti si fanno indietro a me mi è sempre piaciuto, e mi piace ancora.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Infatti, come c'è un'arte di raccontare, solidamente codificata attraverso mille prove ed errori, così c'è pure un'arte dell'ascoltare, altrettanto antica e nobile, a cui tuttavia, che io sappia, non è stata mai data norma.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Conviene essere sempre d'accordo con chi racconta, se no lo si intralcia e gli si fa perdere il filo.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Perché certe imprese per capirle bisogna farle, o almeno vederle;", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "È malinconicamente vero che molti lavori non sono amabili, ma è nocivo scendere in campo carichi di odio preconcetto: chi lo fa, si condanna per la vita a odiare non solo il lavoro, ma se stesso e il mondo.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Si può e si deve combattere perché il frutto del lavoro rimanga nelle mani di chi lo fa, e perché il lavoro stesso non sia una pena, ma l'amore o rispettivamente l'odio per l'opera sono un dato interno, originario, che dipende molto dalla storia dell'individuo, e meno di quanto si creda dalle strutture produttive entro cui il lavoro si svolge.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Perché quando c'è la fame uno si fa furbo.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Perché la brava gente si somiglia dappertutto.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Ma sa come succede quando uno incontra una difficoltà e allora gli pare come se avesse fatto una scommessa e gli spiace di perderla.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Io ho idea che se certi lavori li insegnassero a scuola, invece di Romolo e Remo, si guadagnerebbe.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Io sulle prime credevo che fosse una ragazza un po' strana, perché non avevo esperienza e non sapevo che tutte le ragazze sono strane, o per un verso o per un altro, e se una non è strana vuol dire che è ancora più strana delle altre, appunto perché è fuori quota, non so se mi spiego.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Il termine «libertà» ha notoriamente molti sensi, ma forse il tipo di libertà più accessibile, più goduto soggettivamente, e più utile al consorzio umano, coincide con l'essere competenti nel proprio lavoro, e quindi nel provare piacere a svolgerlo.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Può essere che invece non mi segua il lettore, qui ed altrove, dove è questione di mandrini, di molecole, di cuscinetti a sfere e di capicorda; bene, non so che farci, mi scuso ma sinonimi non ce n'è.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Ma per me un uomo che non abbia mai avuto un collaudo negativo non è un uomo, è come se fosse rimasto alla prima comunione.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "E già difficile per il chimico antivedere, all'infuori dell'esperienza, l'interazione fra due molecole semplici; del tutto impossibile predire cosa avverrà all'incontro di due molecole moderatamente complesse. Che predire sull'incontro di due esseri umani?", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Meglio sbagliare per omissione che per commissione: meglio astenersi dal governare il destino degli altri, dal momento che è già così difficile ed incerto pilotare il proprio.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Se si escludono istanti prodigiosi e singoli che il destino ci può donare, l'amare il proprio lavoro (che purtroppo è privilegio di pochi) costituisce la migliore approssimazione concreta alla felicità sulla terra: ma questa è una verità che non molti conoscono.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Non salutavano, non sorridevano; apparivano oppressi, oltre che da pietà, da un confuso ritegno, che sigillava le loro bocche, e avvinceva i loro occhi allo scenario funereo.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Così per noi anche l'ora della libertà suonò grave e chiusa, e ci riempì gli animi, ad un tempo, di gioia e di un doloroso senso di pudore, per cui avremmo voluto lavare le nostre coscienze e le nostre memorie della bruttura che vi giaceva.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "I codici morali, tutti, sono rigidi per definizione: non ammettono sfumature, né compromessi, né contaminazioni reciproche. Vanno accolti o rifiutati in blocco.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Guerra è sempre.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Fra le cose che avevo imparato in Auschwitz, una delle più importanti era, che bisogna sempre evitare di essere «qualunque». Tutte le vie sono chiuse a chi appare inutile, tutte sono aperte a chi esercita una funzione, anche la più insulsa.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Non è infrequente che dall'urto fra due necessità scaturiscano decisioni insensate, là dove sarebbe più savio lasciare che il dilemma si sciolga per virtù propria.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "L'Unione Sovietica è un gigantesco paese, e alberga nel suo cuore fermenti giganteschi: fra questi, una omerica capacità di gioia e di abbandono, una vitalità primordiale, un talento pagano, incontaminato, per le manifestazioni, le sagre, le baldorie corali.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Nei suoi discorsi, il vero, il possibile e il fantastico erano intrecciati in un groviglio vario e inestricabile.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "La nostalgia è una sofferenza fragile e gentile, essenzialmente diversa, più intima, più umana delle altre pene che avevamo sostenuto fino a quel tempo: percosse, freddo, fame, terrore, destituzione, malattia.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "È antica osservazione che in ogni gruppo umano esiste una vittima predestinata: uno che porta pena, che tutti deridono, su cui nascono dicerie insulse e malevole, su cui, con misteriosa concordia, tutti scaricano i loro mali umori e il loro desiderio di nuocere.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Sono a tavola con la famiglia, o con amici, o al lavoro, o in una campagna verde: in un ambiente insomma placido e disteso, apparentemente privo di tensione e di pena; eppure provo un'angoscia sottile e profonda, la sensazione definita di una minaccia che incombe.", Author = "Primo Levi" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Primo_Levi", Text = "Perché il delfino è simile ad un pesce, eppure partorisce ed allatta i suoi nati? Perché è figlio di un tonno e di una vacca.", Author = "Primo Levi" },
        };
    }
}